/**
 * Open a purchase-day fill-draw craps battle on the Craps table, focused on one wallet's run.
 *
 * The fill draw (CoinDrawBattle, audit 5790a946) is NOT a CrapsBattle field: there is no shared
 * shooter, no seats, no scheduled window and no progressive. Every drawn wallet plays its own dice
 * off the battle word, all at once, so the table races the runs roll for roll: tick N is every
 * run's Nth roll. The felt and dice are the viewer's own; once that run stops, the table rolls on
 * with the dice of the field's longest run until the last rival is done. The pot is rolled into
 * the prize marquee before the first roll.
 *
 * The data path is chain-only and verified: `chainCoinDrawBattle` replays the battle in a worker
 * and returns `replay: null` if any logged figure disagrees. This module then decomposes every run
 * into roll events with `replayCrapsSoloRun`, which must meet every ladder checkpoint again.
 */

import { replayCrapsSoloRun, CRAPS_REPLAY_BET_IDS, CRAPS_REPLAY_FLIP_WEI } from './replay-engine.js';
import { CRAPS_REPLAY_LEG_ORDER } from './replay-contract.js';
import {
  crapsReplaySoloClock,
  crapsReplaySoloFrames,
  crapsReplaySoloOpponent,
  crapsReplayRollsHex,
  loadCrapsReplayProfiles,
  protocolSeatLabel,
} from './replay-adapter.js';

export const COIN_DRAW_ENGINE_VERSION = 'coin-draw-battle-8b380ffe-v1';

const displayFlip = (wei) => (BigInt(wei) / CRAPS_REPLAY_FLIP_WEI).toString();
const normalAddress = (value) => {
  const address = String(value ?? '').trim().toLowerCase();
  return /^0x[0-9a-f]{40}$/.test(address) ? address : null;
};

function compactFlip(wei) {
  const whole = BigInt(wei ?? 0) / CRAPS_REPLAY_FLIP_WEI;
  const tiers = [[1_000_000_000n, 'B'], [1_000_000n, 'M'], [1_000n, 'K']];
  for (const [scale, suffix] of tiers) {
    if (whole >= scale) {
      const tenths = (whole * 10n) / scale;
      return `${tenths / 10n}${tenths % 10n ? `.${tenths % 10n}` : ''}${suffix}`;
    }
  }
  return whole.toString();
}

/** Why the run stopped, in the table's terms: a capped run pays its bankroll, like a goal. */
function capLabel(run) {
  return run.totalRolls >= 200 ? 'ROLL CAP' : 'SHOOTER CAP';
}

/**
 * How the table reads a run's end. A capped run was stopped holding its bankroll and is paid it,
 * as a goal is, so the table locks it rather than busting it.
 */
function tableStop(run) {
  return run.stop === 'bust' ? 'bust' : 'goal';
}

function runTrace(battle, run, index) {
  const boardWei = Object.fromEntries(CRAPS_REPLAY_LEG_ORDER.map((leg) => [leg, BigInt(run.board[leg]) * CRAPS_REPLAY_FLIP_WEI]));
  return replayCrapsSoloRun({
    betId: `${battle.key}:${index}`, player: run.player, boardWei, hands: run.hands, ladderWei: run.ladderWei,
    handsPlayed: run.handsPlayed, totalRolls: run.totalRolls, stop: tableStop(run),
    survivals: run.survivals, boosts: [],
  });
}

function boardChips(run, chip) {
  return Object.freeze(Object.fromEntries(CRAPS_REPLAY_BET_IDS.map((id, i) => [id, Number(BigInt(run.board[CRAPS_REPLAY_LEG_ORDER[i]]) / chip)])));
}

function identityOf(player, profiles) {
  const identity = profiles?.get?.(player) ?? null;
  return { label: protocolSeatLabel(player) || identity?.name || null, avatar: identity?.avatar || null };
}

/**
 * The run whose dice carry the table once the viewer's run is over: the longest, so the clock
 * reaches every rival's last roll. Ties go to the pot winner, then to the first drawn.
 */
function paceIndex(replay) {
  let pace = 0;
  replay.runs.forEach((run, i) => {
    const best = replay.runs[pace];
    if (run.totalRolls > best.totalRolls || (run.totalRolls === best.totalRolls && run.isWinner && !best.isWinner)) pace = i;
  });
  return pace;
}

/**
 * The table options for one replayed run. `battle` is `chainCoinDrawBattle`'s result with a
 * verified `replay`; `index` is the run's first-drawn position.
 */
export function coinDrawRunTableOptions(battle, index, { profiles = null } = {}) {
  const replay = battle?.replay;
  const run = replay?.runs?.[index];
  if (!run) throw new TypeError(`Fill-draw run ${index} was not replayed`);
  const chip = BigInt(replay.chipFlip);
  const traces = replay.runs.map((entry, i) => runTrace(battle, entry, i));
  const trace = traces[index];
  const clock = crapsReplaySoloClock(trace, traces[paceIndex(replay)]);
  const frames = [...crapsReplaySoloFrames(trace, clock)];
  if (run.stop === 'capped') {
    // Name the cap on the run's last roll; the table closes it as a paid lock (see `tableStop`).
    const last = run.totalRolls - 1;
    frames[last] = Object.freeze({ ...frames[last], label: `${String(frames[last].label).replace(/ · GOAL LOCKED$/, '')} · ${capLabel(run)}` });
  }
  const units = Number(run.units);
  const fieldSize = replay.runs.length;
  // The chain's rank, as the table's standing: higher is better, so its ties fall in chain order.
  const standing = (entry) => fieldSize + 1 - Number(entry.rank);
  const otherPlayers = replay.runs.flatMap((entry, i) => (i === index ? [] : [crapsReplaySoloOpponent(traces[i], clock, {
    ...identityOf(entry.player, profiles),
    chips: boardChips(entry, chip),
    bankrollInWei: entry.bankrollInWei,
    goalWei: entry.goalWei,
    paidWei: entry.paidWei,
    standing: standing(entry),
    stop: tableStop(entry),
  })]));
  const viewer = identityOf(run.player, profiles);
  const pot = BigInt(replay.potWei);
  const high = run.ladderWei.reduce((best, value) => (BigInt(value) > best ? BigInt(value) : best), BigInt(run.bankrollInWei));
  const winner = replay.runs[replay.winnerIndex] ?? null;
  return Object.freeze({
    screen: 'battle',
    tableResolved: true,
    showResolution: frames.length > 0,
    tableIndex: battle.key,
    battleSlot: battle.key,
    replayLane: 'main',
    entryKind: 'custom',
    entryLabel: `FILL-DRAW BATTLE${units > 1 ? ` · ${units} UNITS` : ''}`,
    viewerBetId: trace.player.betId,
    viewerPlayer: run.player,
    originalViewerBetId: trace.player.betId,
    viewerLabel: viewer.label,
    viewerDiscordPfp: viewer.avatar,
    viewerResult: Object.freeze({
      stop: tableStop(run),
      handsPlayed: run.handsPlayed,
      exitRoll: Math.max(1, run.totalRolls),
      rawEndingFlip: displayFlip(run.bankrollOutWei),
      highPointFlip: displayFlip(high),
      standing: standing(run),
      // What the chain credited for the run, all units, excluding the pot.
      runPayoutWei: run.paidWei,
    }),
    fieldEntrants: fieldSize,
    rankTimeline: Object.freeze([]),
    entryMultiple: 1,
    bets: boardChips(run, chip),
    playedFlip: (chip * 10n).toString(),
    battleStakeFlip: '0',
    // The pot is what the best paid run wins on top of its own payout: the battle's bounty. It is
    // rolled into the marquee before the first roll.
    bountyPoolWei: pot > 0n ? pot.toString() : null,
    potRoll: pot > 0n,
    addedFlipWei: null,
    bankrollFlip: displayFlip(run.bankrollInWei),
    goalFlip: displayFlip(run.goalWei),
    rolls: crapsReplayRollsHex(trace.hands.map((hand) => hand.events.map((event) => ({ d1: event.d1, d2: event.d2 })))),
    resolutionHands: Object.freeze(frames),
    shooterTimeline: Object.freeze([]),
    otherPlayers: Object.freeze(otherPlayers),
    leaderboardTimeline: Object.freeze([]),
    battleWonByViewer: run.isWinner === true,
    battleWinnerBetId: winner ? `${battle.key}:${replay.winnerIndex}` : null,
    battlePayoutWei: run.isWinner === true && pot > 0n ? pot.toString() : null,
    replayDigest: `${battle.key}:${battle.transactionHash ?? ''}`,
    replayEngineVersion: COIN_DRAW_ENGINE_VERSION,
  });
}

/** One line for the jackpot centre when a replay cannot be shown: the chain's own result. */
export function coinDrawChainResultLine(battle, player) {
  const address = normalAddress(player);
  const row = battle?.runs?.find?.((entry) => normalAddress(entry.player) === address);
  if (!row) return 'This wallet was not drawn into the battle.';
  const paid = BigInt(row.paid);
  return `Your run: ${row.rolls} rolls, ended on ${compactFlip(row.bankrollOut)} FLIP, ${paid > 0n ? `paid ${compactFlip(paid)} FLIP` : 'busted'}.`;
}

// The Craps panel imports the table under this pinned URL (app-craps-entry.js); loading it
// under any other URL would make a second module that defines the element twice.
const CRAPS_TABLE_MODULE = '../components/app-craps-table.js?rev=base-flip-graph-v5';
const CRAPS_TABLE_STYLES = '/app/styles/craps-table.css';

/** Attach the table's lazy stylesheet the way the page loader does, if it has not yet. */
function ensureTableStyles(doc) {
  const link = doc?.querySelector?.(`link[data-href="${CRAPS_TABLE_STYLES}"]`);
  if (!link || link.hasAttribute?.('href')) return;
  const revision = String(link.dataset?.rev || '').trim();
  link.setAttribute?.('href', revision ? `${CRAPS_TABLE_STYLES}?v=${encodeURIComponent(revision)}` : CRAPS_TABLE_STYLES);
}

async function readyTable(doc, timeoutMs) {
  const table = doc?.querySelector?.('app-craps-table');
  if (table?.open) return table;
  const defined = globalThis.customElements?.whenDefined?.('app-craps-table');
  if (!defined) return null;
  // Phones load the Craps panel one idle batch at a time, so the table can still be
  // missing when a battle is opened from the jackpot. Load it now instead of failing.
  ensureTableStyles(doc);
  const load = import(CRAPS_TABLE_MODULE).catch(() => null);
  await Promise.race([Promise.all([defined, load]), new Promise((resolve) => setTimeout(resolve, timeoutMs))]);
  const upgraded = doc?.querySelector?.('app-craps-table');
  return upgraded?.open ? upgraded : null;
}

/**
 * Load the day's battle and open `player`'s run on the page's Craps table.
 * @returns {Promise<{ ok: boolean, message?: string, battle?: object }>}
 */
export async function openCoinDrawRun({
  day,
  player,
  opener = null,
  doc = globalThis.document,
  load = null,
  loadProfiles = loadCrapsReplayProfiles,
  tableTimeoutMs = 12_000,
  signal = null,
} = {}) {
  const address = normalAddress(player);
  if (!address) return { ok: false, message: 'Pick a player to watch their battle run.' };
  const loader = load ?? (await import('../chain/coin-draw.js')).chainCoinDrawBattle;
  const battle = await loader(day, { signal });
  const index = battle.runs.findIndex((row) => normalAddress(row.player) === address);
  if (index < 0) return { ok: false, message: 'This wallet was not drawn into the battle.', battle };
  if (!battle.replay) {
    return { ok: false, message: `Battle replay unavailable. ${coinDrawChainResultLine(battle, address)}`, battle };
  }
  const table = await readyTable(doc, tableTimeoutMs);
  if (!table) return { ok: false, message: 'The Craps table is still loading. Try again in a moment.', battle };
  let profiles = null;
  try { profiles = await loadProfiles(battle.replay.runs.map((run) => run.player)); } catch (_error) { /* identity is decoration */ }
  // A caller that gave up (its deadline passed) must never see the table pop open later.
  if (signal?.aborted) return { ok: false, message: 'The battle took too long to load. Try again.', battle };
  table.open(coinDrawRunTableOptions(battle, index, { profiles }), opener);
  return { ok: true, battle };
}
